practices.solutionCode:
import { useState, useId } from 'react';
export default function SearchableCourses({ courses }) {
  const [query, setQuery] = useState('');
  const inputId = useId();
  const matches = courses.filter(course => course.title.toLowerCase().includes(query.trim().toLowerCase()));
  return <section>
    <label htmlFor={inputId}>Search courses</label>
    <input id={inputId} value={query} onChange={event => setQuery(event.target.value)} />
    {matches.length ? <ul>{matches.map(course => <li key={course.id}>{course.title}</li>)}</ul> : <p>No matching courses.</p>}
  </section>;
}

